def get_conversational_response(query):
    """
    Get appropriate response for conversational queries.
    
    Args:
        query (str): User's input query
        
    Returns:
        str: A randomly selected response from matching patterns, or None if no match
    """
    query_lower = query.lower().strip()
    
    # Check each category for pattern matches
    for category, data in CONV_DB.items():
        for pattern in data["patterns"]:
            if re.search(pattern, query_lower, re.IGNORECASE):
                return random.choice(data["responses"])
    
    return None
